<script>
    function SafeGetValue(obj, path, defaultValue = "") {
        if (!path) return defaultValue;
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) return defaultValue;
        if (typeof current.阶段 === 'string') return current.阶段;
        return String(current);
    }

    function parseLatestValue(fullString) {
        if (typeof fullString !== 'string') {
            return String(fullString);
        }
        let cleanString = fullString.replace(/\s*\(.*\)\s*$/, '');
        const parts = cleanString.split('->');
        return parts[parts.length - 1].trim();
    }

    const pages = document.querySelectorAll('.page');
    const buttons = document.querySelectorAll('.nav-button');
    const contentArea = document.querySelector('.content-area');

    function showPage(pageId) {
        pages.forEach(page => page.classList.remove('active'));
        const activePage = document.getElementById(pageId);
        if (activePage) activePage.classList.add('active');

        buttons.forEach(button => button.classList.remove('active'));
        const activeButton = document.getElementById(`btn-${pageId.split('-')[1]}`);
        if(activeButton) activeButton.classList.add('active');
    }

    buttons.forEach(button => {
        button.addEventListener('click', () => {
             const pageId = `page-${button.id.split('-')[1]}`;
             showPage(pageId);
        });
    });

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.querySelector('.status-container').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据。</p>";
                return;
            }
            const gameData = messages[0].data;
            const charData = gameData.display_data || gameData.stat_data;
            if (!charData) {
                document.querySelector('.status-container').innerHTML = "<p style='color:red; padding:10px;'>角色数据丢失。</p>";
                return;
            }

            if (charData.hasOwnProperty('世界')) {
                const year = parseLatestValue(SafeGetValue(charData, '世界.年分', ''));
                const month = parseLatestValue(SafeGetValue(charData, '世界.月份', ''));
                const day = parseLatestValue(SafeGetValue(charData, '世界.日期', ''));
                const weekday = parseLatestValue(SafeGetValue(charData, '世界.星期', ''));
                document.getElementById('world-date').innerText = `${year}年${month}月${day}日 ${weekday}`;
                document.getElementById('world-time').innerText = parseLatestValue(SafeGetValue(charData, '世界.時間', '00:00'));
            }

            const sisters = ['ichika', 'futaba', 'miku', 'shiki', 'satsuki'];
            const sisterKeys = {'ichika': '一香', 'futaba': '二葉', 'miku': '美空', 'shiki': '四季', 'satsuki': '五月'};

            sisters.forEach(sister => {
                const key = sisterKeys[sister];
                if (charData.hasOwnProperty(key)) {
                    document.getElementById(`${sister}-location`).innerText = parseLatestValue(SafeGetValue(charData, `${key}.地點`, '未知'));
                    document.getElementById(`${sister}-thoughts`).innerText = parseLatestValue(SafeGetValue(charData, `${key}.心聲`, '...'));
                    document.getElementById(`${sister}-plan`).innerText = parseLatestValue(SafeGetValue(charData, `${key}.當前計畫`, '...'));
                    document.getElementById(`${sister}-stage`).innerText = parseLatestValue(SafeGetValue(charData, `${key}.與{{user}}的關係.階段`, '...'));
                }
            });

            showPage('page-ichika');

        } catch (error) {
            document.querySelector('.status-container').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
